class SandboxRuntimeServiceClient(ConnectClient):
    """
    What runs inside one sandbox: commands, files, the desktop, coding agents, links. Answered by
    the sandbox's own server at Connection.url, with `Authorization: Bearer <Connection.token>`;
    Connection.url is the sandbox's server, the same for every sandbox there, so one connection
    serves them all. Every request names its sandbox; a token for another sandbox is
    `PERMISSION_DENIED`. Commands run as `user` (with passwordless sudo, when the template's image
    has sudo: ours do) in /home/user unless a request says otherwise. Paths are absolute, or
    relative to /home/user.

    Its refusals, beside the header's: INVALID_ARGUMENT = a bad field, named, or a request_id sent
    again with other fields. FAILED_PRECONDITION = as the RPC says. UNAUTHENTICATED = a token is
    missing, wrong, expired or revoked (UpdateSandbox.revoke_tokens). `UNAUTHENTICATED`,
    `PERMISSION_DENIED` (a token of another server, after a move) and `NOT_FOUND` (the server let
    the sandbox go to another) answer a call that did nothing: connect again and repeat it.

    Bounds: a response holds ~64 KiB at most, but for ReadFile (up to 1 MiB) and ControlDesktop's
    screenshot; a file of any size moves through CreateLink. A request holds 1 MiB at most (a
    command with its stdin, a prompt), but WriteFiles's 17 MiB; and a message the sandbox made
    larger than 1 MiB and the rest of its answer (a screenshot: 17 MiB) is never passed on. A caller
    has 60 s, and a second more for each 64 KiB, to send its request and to take each message: one
    slower loses the call. A sandbox serves 64 calls at once, streams, links and SSH channels
    included, a WriteFiles or a ControlDesktop counting as 16. A message over its bound, or a call
    past the 64, is RESOURCE_EXHAUSTED without LimitReached: end one, or wait.

    A sandbox keeps the request_ids of what runs in it (RunCommand, PromptAgent) on its disk,
    unsynced: one that lost its memory (STOPPED) may have lost those of its last seconds too, and a
    retry of one of them runs again.
    """
    async def run_command(
        self,
        request: RunCommandRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> Command:
        """
        Runs a shell command and waits for it (wait_seconds): its exit and output, or RUNNING with
        its output so far while it runs on. Only timeout_seconds or StopCommand ends it early.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="RunCommand",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=RunCommandRequest,
                output=Command,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def get_command(
        self,
        request: GetCommandRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> Command:
        """
        A command, after waiting for it to end (wait_seconds). The last 100 that ended are kept.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="GetCommand",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=GetCommandRequest,
                output=Command,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )

    async def stop_command(
        self,
        request: StopCommandRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> Command:
        """
        SIGTERM, then SIGKILL 10 s later if it still runs. Answers once it has ended. A command that
        has ended has what it left running killed at once: its background jobs, or a fork bomb.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="StopCommand",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=StopCommandRequest,
                output=Command,
                idempotency_level=IdempotencyLevel.IDEMPOTENT,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def list_commands(
        self,
        request: ListCommandsRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> ListCommandsResponse:
        """
        The commands running now, started by the API, SSH or a terminal, without their
        output.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ListCommands",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=ListCommandsRequest,
                output=ListCommandsResponse,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )

    def watch_command(
        self,
        request: WatchCommandRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> AsyncIterator[CommandOutput]:
        """
        A command's output from the last 64 KiB, then live, until it ends.
        """
        return self.execute_server_stream(
            request=request,
            method=MethodInfo(
                name="WatchCommand",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=WatchCommandRequest,
                output=CommandOutput,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def read_file(
        self,
        request: ReadFileRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> File:
        """
        A file's text (its bytes, if it is not UTF-8), from offset_bytes. A file that is not UTF-8 is
        answered to an MCP tool by its size alone: CreateLink download_path fetches it, RunCommand
        (`file`, `xxd`) looks inside.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ReadFile",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=ReadFileRequest,
                output=File,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )

    async def list_files(
        self,
        request: ListFilesRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
        use_get: bool = False,
    ) -> ListFilesResponse:
        """
        A directory's entries, `depth` levels deep, 1000 a page. A file's path lists that file alone.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ListFiles",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=ListFilesRequest,
                output=ListFilesResponse,
                idempotency_level=IdempotencyLevel.NO_SIDE_EFFECTS,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
            use_get=use_get,
        )

    async def write_files(
        self,
        request: WriteFilesRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> WriteFilesResponse:
        """
        Changes files in order (writes, edits, moves, deletes, directories), and stops at the first
        that fails. A write replaces the file whole, keeping its owner and mode: a hard link to it
        keeps the old content; a symbolic link is written through to its target.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="WriteFiles",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=WriteFilesRequest,
                output=WriteFilesResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    def watch_files(
        self,
        request: WatchFilesRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> AsyncIterator[FileEvent]:
        """
        Changes under a directory, live, until the stream is closed.
        """
        return self.execute_server_stream(
            request=request,
            method=MethodInfo(
                name="WatchFiles",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=WatchFilesRequest,
                output=FileEvent,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def control_desktop(
        self,
        request: ControlDesktopRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> ControlDesktopResponse:
        """
        Does the actions in order, then answers with a screenshot of the screen as they left it.
        Stops at the first that fails; with no actions, just the screenshot. The first starts the
        desktop, which takes some seconds. FAILED_PRECONDITION = the desktop did not start (its
        words).
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="ControlDesktop",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=ControlDesktopRequest,
                output=ControlDesktopResponse,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

    async def create_link(
        self,
        request: CreateLinkRequest,
        *,
        headers: Headers | Mapping[str, str] | None = None, 
        timeout_ms: int | None = None,
    ) -> Link:
        """
        A URL, for a browser or curl, into one thing of the sandbox: a terminal, the screen, a file
        to download or upload; or a private port's address and a token for it. It expires. A
        download or upload link works once. Making one wakes nothing.

        A private port answers only a request that sends its token as the header `Pethost-Token:
        <token>`: a program's, curl's, a page's fetch. The server checks it before anything wakes and
        takes the header off; the rest reaches the program as it was sent, Authorization and Cookie
        included. A preflight that names the header is answered 204 by the server itself, and the
        answer to a request whose token it took carries Access-Control-Allow-Origin with the request's
        origin, without credentials, so that a page of any origin may call the port with a token it
        holds. A browser's tab, a WebSocket or an image sends no such header: what a browser opens is a
        public port (Ingress), or a port forwarded by `ssh -L`. Every sandbox's address is under one
        domain: the server takes the Domain off a cookie an answer sets, and an app keeps the cookies
        its pages set to its own address with the `__Host-` prefix.
        """
        return await self.execute_unary(
            request=request,
            method=MethodInfo(
                name="CreateLink",
                service_name="pethost.sandboxes.v1.SandboxRuntimeService",
                input=CreateLinkRequest,
                output=Link,
                idempotency_level=IdempotencyLevel.UNKNOWN,
            ),
            headers=headers,
            timeout_ms=timeout_ms,
        )

